mapper.update:
update dish
set status = #{status}
where id = #{id}

update dish_flavor
set name = #{name}, value = #{value}
where dish_id = #{dishId}

mapper.select:
select dish.id, dish.name, category_id, price, image, description, dish.status, dish.create_time, dish.update_time, dish.create_user,dish.update_user, category.name as category_name from dish left join category on dish.category_id = category.id
category_id = #{categoryId}
and name like concat('%', #{name}, '%')
and status = #{status}
order by id desc
